const input = $input.first().json;
const allowedStatuses = new Set(['valid', 'needs_review']);
const excludedOfferStatuses = new Set(['duplicate', 'rejected']);
const dateOnly = (value) => value ? String(value).slice(0, 10) : '';
const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const groups = new Map();
const counters = { input_rows: input.rows.length, exported_rows: 0, duplicate_rows: 0, rejected_rows: 0 };
for (const row of input.rows) {
  if (excludedOfferStatuses.has(row.status)) { counters.duplicate_rows += row.status === 'duplicate' ? 1 : 0; counters.rejected_rows += row.status === 'rejected' ? 1 : 0; continue; }
  if (!allowedStatuses.has(row.normalization_status)) { counters.rejected_rows += 1; continue; }
  const company = clean(row.declared_company_name || row.company_name || 'Entreprise non déclarée');
  const city = clean(row.city || row.location_label || 'Localisation non déclarée');
  const key = `${company}|${city}`;
  if (!groups.has(key)) groups.set(key, { run_id: input.run_id, generated_at: input.generated_at, declared_company_name: company, city, offer_keys: new Set(), titles: new Set(), dates: [] });
  const group = groups.get(key);
  const offerKey = row.canonical_offer_key || row.offer_key;
  if (offerKey) group.offer_keys.add(offerKey);
  if (row.title) group.titles.add(clean(row.title));
  if (row.published_at) group.dates.push(dateOnly(row.published_at));
}
const business_rows = [...groups.values()].map((group) => ({ run_id: group.run_id, generated_at: group.generated_at, declared_company_name: group.declared_company_name, city: group.city, offer_count: group.offer_keys.size, titles: [...group.titles].sort().join('; '), first_published_at: group.dates.sort()[0] || '', last_published_at: group.dates.sort().slice(-1)[0] || '', source_offer_keys: [...group.offer_keys].sort().join('; ') })).sort((a, b) => `${a.declared_company_name}|${a.city}`.localeCompare(`${b.declared_company_name}|${b.city}`, 'fr-FR'));
counters.exported_rows = business_rows.length;
return [{ json: { ...input, business_rows, counters } }];

const input = $input.first().json;
const columns = ['run_id', 'generated_at', 'declared_company_name', 'city', 'offer_count', 'titles', 'first_published_at', 'last_published_at', 'source_offer_keys'];
const escapeCsv = (value) => `"${String(value ?? '').replace(/"/g, '""').replace(/\r?\n/g, ' ')}"`;
const lines = [columns.map(escapeCsv).join(',')];
for (const row of input.business_rows) lines.push(columns.map((column) => escapeCsv(row[column])).join(','));
const generatedCompact = input.generated_at.replace(/[-:]/g, '').replace(/\.\d+Z$/, 'Z');
const file_name = `france-travail-company-slice-${input.run_id}-${generatedCompact}.csv`;
return [{ json: { ...input, csv_columns: columns, csv_content_utf8_bom: `\ufeff${lines.join('\r\n')}\r\n`, file_path: `${input.output_directory}/${file_name}`, file_name } }];
